import{_ as i,B as r,o as s,c as l,a as t,f as n,E as o,a8 as d}from"./chunks/framework.CNIpabDg.js";const v=JSON.parse('{"title":"Development environments and targets","description":"Understand the independent Core, Applications and Platforms development and runtime targets.","frontmatter":{"layout":"doc","docType":"explanation","description":"Understand the independent Core, Applications and Platforms development and runtime targets."},"headers":[],"relativePath":"explanation/development-environments.md","filePath":"explanation/development-environments.md","lastUpdated":1793145952000}'),p={name:"explanation/development-environments.md"};function m(u,e,h,c,f,b){const a=r("CodeReference");return s(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[9]||(e[9]=t("h1",{id:"development-environments-and-targets",tabindex:"-1"},[n("Development environments and targets "),t("a",{class:"header-anchor",href:"#development-environments-and-targets","aria-label":'Permalink to "Development environments and targets"'},"​")],-1)),e[10]||(e[10]=t("p",null,[n("The three Xila workspaces have different responsibilities and independent Cargo/mise setups. The portable libraries are developed in "),t("strong",null,"Core"),n("; "),t("strong",null,"Applications"),n(" builds Wasmi and WASI app logic; "),t("strong",null,"Platforms"),n(" supplies platform-specific drivers, the final native/browser assembly and images.")],-1)),e[11]||(e[11]=t("h2",{id:"workspace-and-tool-boundaries",tabindex:"-1"},[n("Workspace and tool boundaries "),t("a",{class:"header-anchor",href:"#workspace-and-tool-boundaries","aria-label":'Permalink to "Workspace and tool boundaries"'},"​")],-1)),t("ul",null,[t("li",null,[e[0]||(e[0]=t("strong",null,"Core",-1)),e[1]||(e[1]=n(": portable Task, VFS, Time, Graphics, Network, ABI and shared libraries; host Rustdoc deployment. Source: ",-1)),o(a,{path:"mise.toml"}),e[2]||(e[2]=n(".",-1))]),t("li",null,[e[3]||(e[3]=t("strong",null,"Applications",-1)),e[4]||(e[4]=n(": WASI guest applications, guest bindings, the host Wasmi runtime, shells and other native executables; application localization and development package workflows. Source: ",-1)),o(a,{repo:"applications",path:"mise.toml"}),e[5]||(e[5]=n(".",-1))]),t("li",null,[e[6]||(e[6]=t("strong",null,"Platforms",-1)),e[7]||(e[7]=n(": display/audio/network platform drivers, example runtimes, OPFS, LittleFS reference image generation, container image and browser demonstration publishing. Source: ",-1)),o(a,{repo:"platforms",path:"mise.toml"}),e[8]||(e[8]=n(".",-1))])]),e[12]||(e[12]=d('<p>Mise selects pinned Rust/Node/tool versions on demand. mr-boxington compilation caching and CI tool bootstrap remain repository-specific. All repositories pin external Git dependencies; local adjacent checkouts require an explicit Cargo patch or their pinned versions will still be selected.</p><h2 id="three-execution-targets" tabindex="-1">Three execution targets <a class="header-anchor" href="#three-execution-targets" aria-label="Permalink to &quot;Three execution targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>What it runs</th><th>Owned by</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td>Native Xila runtime and host tests</td><td>Platforms (with Core + Applications dependencies)</td></tr><tr><td><code>wasm32-wasip1</code></td><td>WASI guest apps interpreted by Wasmi inside Xila</td><td>Applications</td></tr><tr><td><code>wasm32-unknown-unknown</code></td><td>Browser-hosted Xila final binary using OPFS and browser drivers</td><td>Platforms</td></tr></tbody></table><p>The <code>xila-wasm</code> crate lives in Applications and owns <strong>both</strong> Wasmi host integration and guest-facing bindings. Core contains neither a standalone guest interpreter nor the browser example.</p><h2 id="distribution-and-runtime-isolation" tabindex="-1">Distribution and runtime isolation <a class="header-anchor" href="#distribution-and-runtime-isolation" aria-label="Permalink to &quot;Distribution and runtime isolation&quot;">​</a></h2><p>The Linux/amd64 headless OCI runtime is assembled/published by Platforms, separate from the mise development environment. Its host filesystem mounts and permissions remain part of the runtime policy; Docker&#39;s isolation is not proof of MCU security.</p><p>Core publishes <strong>only its host Rust API</strong> at <a href="https://documentation.xila.dev/" target="_blank" rel="noreferrer">documentation.xila.dev</a>; the browser demo and localized builds now live at <a href="https://platforms.xila.dev/" target="_blank" rel="noreferrer">platforms.xila.dev</a>. Applications&#39; guest Rustdoc is not currently published under Core&#39;s old <code>/guest/</code> path; use the <a href="/reference/guest.html">guest source reference</a> until it has a dedicated publishing pipeline.</p><h2 id="validation-limits" tabindex="-1">Validation limits <a class="header-anchor" href="#validation-limits" aria-label="Permalink to &quot;Validation limits&quot;">​</a></h2><p>Compilation and CI only cover selected target/feature combinations. In particular, the Espressif code retained in Platforms needs a board-specific toolchain, power/flash/RAM measurement and validation. A successful Linux/browser integration check alone is <strong>not</strong> proof of a working ESP32-S3 port.</p><p>Continue with <a href="/how-to/setup-development.html">Development setup</a>, <a href="/reference/development-commands.html">Development commands</a> and the <a href="/tutorials/native.html">native</a> or <a href="/tutorials/browser.html">browser</a> tutorial.</p>',10))])}const x=i(p,[["render",m]]);export{v as __pageData,x as default};
